WITH unpacked AS (SELECT id, plan, effective_from, currency, ELEMENT_AT(tier_prices, 1) AS entry_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers) SELECT currency, AVG(lowest_price) FILTER (WHERE plan = 'enterprise') AS enterprise_avg_lowest_price, ROUND(SUM(lowest_price) / NULLIF(COUNT(CASE WHEN currency = 'THB' THEN 1 END), 0), 2) AS lowest_price_per_thb, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, SUM(CASE WHEN currency = 'EUR' THEN entry_price ELSE 0 END) AS eur_entry_price, SUM(lowest_price) FILTER (WHERE plan = 'basic') AS basic_total_lowest_price FROM unpacked GROUP BY currency ORDER BY basic_total_lowest_price DESC;
